INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einem Benutzerhandbuch?', 2, '[{"text": "Anleitung für Systemnutzung", "correct": true, "because": "Hilft Nutzern"}, {"text": "Technisches Wartungshandbuch", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Benutzerhandbuch?', 3, '[{"text": "Nutzern Bedienung erleichtern", "correct": true, "because": "Verständlichkeit fördern"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Systemleistung steigern", "correct": false, "because": "Kein technisches Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Benutzerhandbuch?', 5, '[{"text": "Schritt-für-Schritt-Anleitungen", "correct": true, "because": "Praktische Hilfe"}, {"text": "FAQ-Bereich", "correct": true, "because": "Häufige Fragen beantworten"}, {"text": "Marketingstrategie", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Benutzerhandbuch muss verständlich sein. b) Es ist nur für Softwareentwickler nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Für Endnutzer, nicht Entwickler"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung eines Benutzerhandbuchs?', 4, '[{"text": "Zielgruppenanalyse", "correct": false, "because": "Wichtig für Verständlichkeit"}, {"text": "Klarheit der Sprache", "correct": false, "because": "Kern der Dokumentation"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Benutzerhandbuch Screenshots enthalten sollte?', 2, '[{"text": "Ja", "correct": true, "because": "Visuelle Hilfe"}, {"text": "Nein", "correct": false, "because": "Oft empfohlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein Benutzerhandbuch für Fachinformatiker?', 3, '[{"text": "Unterstützung der Nutzer", "correct": true, "because": "Erleichtert Bedienung"}, {"text": "Hardwarewartung", "correct": false, "because": "Anderer Bereich"}, {"text": "Marketing", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Erstellung eines Benutzerhandbuchs?', 5, '[{"text": "Funktionsbeschreibungen", "correct": true, "because": "Erklärt System"}, {"text": "Fehlerbehebung", "correct": true, "because": "Lösungen für Probleme"}, {"text": "Bürogestaltung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Benutzerhandbuch reduziert Supportanfragen. b) Es ist nur für komplexe Systeme nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch einfache Systeme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Benutzerhandbuch unwichtig?', 4, '[{"text": "Verständlichkeit", "correct": false, "because": "Kernprinzip"}, {"text": "Struktur", "correct": false, "because": "Übersicht nötig"}, {"text": "Farbe der Schrift", "correct": true, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Benutzerhandbuch digital sein?', 2, '[{"text": "Nein", "correct": true, "because": "Auch gedruckt möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Benutzerhandbuch für Fachinformatiker?', 4, '[{"text": "Weniger Supportaufwand", "correct": true, "because": "Selbsthilfe"}, {"text": "Bessere Nutzererfahrung", "correct": true, "because": "Klarheit"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Benutzerhandbuch nur für Endnutzer ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Administratoren"}, {"text": "Ja", "correct": false, "because": "Breiter anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Benutzerhandbuch?', 3, '[{"text": "Klarheit", "correct": true, "because": "Verständlichkeit"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Design", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Benutzerhandbuch enthält Bedienhinweise. b) Es ist nur für Software nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Hardware"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein fehlendes Benutzerhandbuch?', 5, '[{"text": "Mehr Supportanfragen", "correct": true, "because": "Keine Selbsthilfe"}, {"text": "Nutzerschwierigkeiten", "correct": true, "because": "Unklarheit"}, {"text": "Schnellere Nutzung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker beim Benutzerhandbuch?', 3, '[{"text": "Erstellung und Pflege", "correct": true, "because": "Dokumentation"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Benutzerhandbuch online bereitgestellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Digitale Zugänglichkeit"}, {"text": "Nein", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Fachinformatiker für ein Benutzerhandbuch nutzen?', 4, '[{"text": "Confluence", "correct": true, "because": "Dokumentationssoftware"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
